async function px(e, t) {
	let n = await e.getRecord({
		tagName: "BehaviorDescription",
		id: t
	});
	if (!n) return [];
	let r = (await e.findAncestors(n, { depth: 1 }))[0];
	if (r?.tagName === "LNode") return [r];
	if (r) {
		let t = (await e.findDescendants(r, { collect: ["LNode"] })).LNode ?? [];
		if (t.length > 0) return t;
	}
	return await e.getRecordsByTagName("LNode");
}
